<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue'
import {ElMessage} from 'element-plus'
import {api,post,download,stamp} from '../api'
const rows=ref<any[]>([]),settings=ref<any>({factory:'智造 MES',backupIntervalHours:'24',backupRetentionDays:'30'}),preview=ref<any>(),confirmation=ref(''),id=ref(''),busy=ref(false),status=ref<any>();let timer:ReturnType<typeof setInterval>
async function load(){try{rows.value=await api('/api/backups');status.value=await api('/api/maintenance')}catch{}}
async function create(){await post('/api/backups');await load()}
async function preflight(row:any){busy.value=true;try{id.value=row.id;preview.value=await post('/api/backups/'+row.id+'/preview');confirmation.value=''}catch(e:any){ElMessage.error(e.message)}finally{busy.value=false}}
async function restore(){try{await post('/api/backups/'+id.value+'/restore',{ticket:preview.value.ticket,confirmation:confirmation.value});preview.value=null;ElMessage.warning('开始维护恢复，完成后会退出全部会话，请重新登录');await load()}catch(e:any){ElMessage.error(e.message)}}
async function save(){try{await api('/api/admin/settings',{method:'PUT',body:JSON.stringify(settings.value)});ElMessage.success('配置已保存')}catch(e:any){ElMessage.error(e.message)}}
onMounted(async()=>{await load();for(const s of await api('/api/admin/settings'))settings.value[s.key]=s.value;timer=setInterval(load,4000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><section class="panel"><h2>系统配置与自动备份</h2><el-form label-width="150"><el-form-item label="工厂名称"><el-input v-model="settings.factory"/></el-form-item><el-form-item label="备份间隔（小时）"><el-input v-model="settings.backupIntervalHours" type="number"/></el-form-item><el-form-item label="保留天数"><el-input v-model="settings.backupRetentionDays" type="number"/></el-form-item></el-form><el-button @click="save">保存配置</el-button><el-button type="primary" @click="create">立即备份数据库与附件</el-button><p class="sub">真实 PostgreSQL 备份，包含 SOP、附件和非密钥配置。下载后应另存到独立介质。</p></section><section class="panel"><el-alert v-if="status?.status!=='Idle'" :title="'维护状态：'+status?.status" :description="status?.error" :closable="false"/><el-table :data="rows"><el-table-column label="时间"><template #default="{row}">{{stamp(row.at)}}</template></el-table-column><el-table-column prop="status" label="状态"/><el-table-column prop="error" label="错误"/><el-table-column label="操作"><template #default="{row}"><el-button :disabled="row.status!=='Completed'" @click="download('/api/backups/'+row.id+'/download','mes-backup-'+row.id+'.zip')">下载</el-button><el-button :disabled="row.status!=='Completed'||busy" type="danger" @click="preflight(row)">恢复前校验</el-button></template></el-table-column></el-table></section><el-dialog :model-value="!!preview" title="管理员确认恢复范围" width="760" @close="preview=null"><template v-if="preview"><el-alert :title="preview.scope" type="warning" :closable="false"/><p>备份时间：{{stamp(preview.manifest.createdAt)}}；附件数：{{Object.keys(preview.manifest.files).length}}</p><p>数据库与文件摘要校验通过。恢复将替换当前业务状态，先自动备份当前状态。请输入：</p><code>{{preview.confirmation}}</code><el-input v-model="confirmation" placeholder="输入上方完整确认文字"/><el-button type="danger" :disabled="confirmation!==preview.confirmation" @click="restore">确认并开始恢复</el-button></template></el-dialog></template>
